const msg = $json.message || {};
const userMessage = String(msg.text || msg.caption || '').trim() || '(non-text message)';
const chatId = String(msg.chat?.id || '');

function normalize(value) {
  return String(value || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

function hasAny(text, words) {
  return words.some(w => text.includes(w));
}

const q = normalize(userMessage);
const french = hasAny(q, [' quels ', ' quelle ', ' combien ', ' peux ', ' facture', ' lien', ' paiement', ' devis', ' depense', ' resume', ' stp', ' tu ', ' des '].map(w => w.trim()));
let intent = 'global_summary';
let incompleteRequest = false;

if (hasAny(q, ['weekly summary', 'resume hebdo', 'resume de la semaine', 'bilan semaine', 'bilan hebdo'])) {
  intent = 'weekly_summary';
  incompleteRequest = /\b(of|de|pour)\s*$/.test(q);
} else if (hasAny(q, ['contribution', 'contributions', 'contributed', 'contribute', 'money in', 'incoming money', 'tenant bond', 'PAYER_C', 'apport', 'apports'])) {
  intent = 'contributions';
} else if (hasAny(q, ['operating expense', 'operating expenses', 'operating cost', 'operating costs', 'running cost', 'utilities', 'holding cost', 'depense exploitation', 'depenses exploitation', 'charges courantes', 'charges exploitation'])) {
  intent = 'operating_expenses';
} else if (hasAny(q, ['invoice', 'invoices', 'facture', 'factures', 'bill', 'bills'])) {
  intent = 'invoices';
} else if (hasAny(q, ['unpaid', 'pending', 'overdue', 'due soon', 'to pay', 'payable', 'owed', 'payment alert', 'need to pay', 'impaye', 'impayes', 'a payer', 'en attente'])) {
  intent = 'pending_payments';
} else if (hasAny(q, ['payments', 'payment row', 'payment rows', 'paiements', 'paiement'])) {
  intent = 'payments';
} else if (hasAny(q, ['timeline', 'history', 'progress', 'update', 'updates', 'milestone', 'event', 'events', 'news', 'historique', 'evenement', 'evenements', 'dernieres news', 'derniers evenements'])) {
  intent = 'timeline';
} else if (hasAny(q, ['quote', 'quotes', 'quotation', 'estimate', 'proposal', 'tender', 'devis'])) {
  intent = 'quotes';
} else if (hasAny(q, ['gmail', 'drive', 'link', 'links', 'lien', 'liens', 'url', 'source'])) {
  intent = 'links_lookup';
} else if (hasAny(q, ['document', 'documents', 'pdf', 'file', 'piece jointe', 'pieces jointes', 'recu', 'recus'])) {
  intent = 'documents';
} else if (hasAny(q, ['need review', 'needs review', 'a verifier', 'verification'])) {
  intent = 'timeline';
}

const memoryRange = 'Agent_Memory!A1:E6000';
const rangesByIntent = {
  links_lookup: [
    'Payments!A1:V700',
    'Invoices!A1:AH600',
    'Timeline!A1:N700',
    'Operating_Expenses!A1:AF600',
    'Quotes!A1:P600',
    'Documents!A1:N900',
    memoryRange
  ],
  weekly_summary: [
    'Payments!A1:V700',
    'Contributions!A1:O800',
    'Timeline!A1:N700',
    'Operating_Expenses!A1:AF600',
    'Quotes!A1:P600',
    'Documents!A1:N900',
    memoryRange
  ],
  operating_expenses: [
    'Operating_Expenses!A1:AF600',
    'Documents!A1:N900',
    memoryRange
  ],
  invoices: [
    'Invoices!A1:AH600',
    'Payments!A1:V700',
    'Documents!A1:N900',
    memoryRange
  ],
  payments: [
    'Payments!A1:V700',
    'Documents!A1:N900',
    'Invoices!A1:AH600',
    memoryRange
  ],
  pending_payments: [
    'Payments!A1:V700',
    'Invoices!A1:AH600',
    'Operating_Expenses!A1:AF600',
    'Documents!A1:N900',
    memoryRange
  ],
  contributions: [
    'Contributions!A1:O800',
    'Documents!A1:N700',
    memoryRange
  ],
  quotes: [
    'Quotes!A1:P600',
    'Payments!A1:V700',
    'Documents!A1:N700',
    'Timeline!A1:N600',
    memoryRange
  ],
  documents: [
    'Documents!A1:N900',
    'Payments!A1:V700',
    'Invoices!A1:AH600',
    'Operating_Expenses!A1:AF600',
    'Quotes!A1:P600',
    'Timeline!A1:N700',
    memoryRange
  ],
  timeline: [
    'Timeline!A1:N700',
    'Payments!A1:V700',
    'Documents!A1:N900',
    memoryRange
  ],
  global_summary: [
    'Payments!A1:V700',
    'Contributions!A1:O800',
    'Quotes!A1:P500',
    'Timeline!A1:N700',
    'Documents!A1:N900',
    memoryRange
  ]
};

const ranges = rangesByIntent[intent] || rangesByIntent.global_summary;
if (!ranges.includes('Dashboard!A1:Z200')) ranges.push('Dashboard!A1:Z200');
const query = ranges.map(r => 'ranges=' + encodeURIComponent(r)).join('&');
const fetchUrl = 'https://sheets.googleapis.com/v4/spreadsheets/REPLACE_WITH_YOUR_SHEET_ID/values:batchGet?majorDimension=ROWS&' + query;

return { json: {
  userMessage,
  chatId,
  responseLanguage: french ? 'French' : 'English',
  intent,
  incompleteRequest,
  ranges,
  fetchUrl,
  tokenSafetyMode: 'v4_reliable_links_verified_totals',
  timestamp: new Date().toISOString()
}};

const route = $('Normalize + Route').item.json;
const batch = $input.item.json.valueRanges || [];

function sheetName(rangeName) {
  return String(rangeName || '').split('!')[0].replace(/^'/, '').replace(/'$/, '');
}
function parse(range) {
  if (!range?.values || range.values.length < 2) return [];
  const headers = range.values[0].map(h => String(h || '').trim());
  return range.values.slice(1)
    .filter(row => row.some(cell => String(cell || '').trim() !== ''))
    .map(row => Object.fromEntries(headers.map((h, i) => [h, row[i] ?? ''])));
}
const sheetData = {};
for (const range of batch) {
  const name = sheetName(range.range);
  if (name) sheetData[name] = parse(range);
}
function normKey(value) {
  return String(value || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '');
}
function get(row, aliases) {
  const map = {};
  for (const [key, value] of Object.entries(row || {})) map[normKey(key)] = value;
  for (const alias of aliases) {
    const value = map[normKey(alias)];
    if (value !== undefined && value !== null && String(value).trim() !== '') return value;
  }
  return '';
}
function amount(value) {
  const raw = String(value ?? '').trim().replace(/[\s\u00A0\u202F]/g, '').replace(/[^0-9,.-]/g, '');
  if (!raw) return 0;
  const comma = raw.lastIndexOf(',');
  const dot = raw.lastIndexOf('.');
  let normalized = raw;
  if (comma > dot) normalized = raw.replace(/\./g, '').replace(',', '.');
  else if (dot > comma && comma >= 0) normalized = raw.replace(/,/g, '');
  else if (comma >= 0) normalized = raw.replace(',', '.');
  const number = Number(normalized);
  return Number.isFinite(number) ? number : 0;
}
function compactRow(row, keys, maxChars = 220) {
  const out = {};
  for (const [label, aliases] of Object.entries(keys)) {
    const value = get(row, Array.isArray(aliases) ? aliases : [aliases]);
    if (value !== '') {
      const isLink = /drive|gmail|document|statement|link/i.test(label);
      out[label] = String(value).slice(0, isLink ? 2000 : maxChars);
    }
  }
  return out;
}
function status(row) {
  return String(get(row, ['Status']) || '').trim().toUpperCase().replace(/\s+/g, '_');
}
function needsReview(row) {
  return /YES|TRUE|REVIEW/i.test(String(get(row, ['Need Review', 'Need_Review']) || ''));
}
function hasLink(row) {
  return Boolean(get(row, ['Drive_Link', 'Linked Documents', 'Gmail_Link', 'Gmail Link', 'Links to Gmail', 'Statement Link']));
}
function sortByDateDesc(rows, dateAliases = ['Date'], updatedAliases = ['Updated_At', 'Created_At']) {
  return [...(rows || [])].sort((a, b) => {
    const aUpdated = Date.parse(String(get(a, updatedAliases) || '')) || 0;
    const bUpdated = Date.parse(String(get(b, updatedAliases) || '')) || 0;
    const aDate = Date.parse(String(get(a, dateAliases) || '')) || 0;
    const bDate = Date.parse(String(get(b, dateAliases) || '')) || 0;
    return (bDate - aDate) || (bUpdated - aUpdated);
  });
}
function cap(rows, max) {
  return (rows || []).slice(0, max);
}
function paid(row) {
  return /PAID|AUTO_PAID|DEPOSIT_PAID|PARTIALLY_PAID/i.test(status(row));
}
function totalsBy(rows, groupAliases, amountAliases) {
  const totals = {};
  for (const row of rows || []) {
    const label = String(get(row, groupAliases) || 'Unknown');
    totals[label] = (totals[label] || 0) + amount(get(row, amountAliases));
  }
  return Object.fromEntries(Object.entries(totals).map(([label, value]) => [label, value.toFixed(2)]));
}
function inLastDays(row, aliases, days) {
  const timestamp = Date.parse(String(get(row, aliases) || ''));
  if (!timestamp) return false;
  return timestamp >= Date.now() - days * 86400000;
}

const payments = sheetData.Payments || [];
const invoices = sheetData.Invoices || [];
const operatingExpenses = sheetData.Operating_Expenses || [];
const contributions = sheetData.Contributions || [];
const quotes = sheetData.Quotes || [];
const timeline = sheetData.Timeline || [];
const documents = sheetData.Documents || [];
const memory = sheetData.Agent_Memory || [];

const paymentKeys = {
  Date: ['Date we got Invoice', 'Date Paid'],
  Type: ['Expense Type'],
  Description: ['Description/Task'],
  Amount: ['Amount'],
  Status: ['Status'],
  NeedReview: ['Need Review'],
  PaymentID: ['Payment_ID'],
  Documents: ['Linked Documents', 'Drive_Link'],
  Gmail: ['Links to Gmail']
};
const documentKeys = {
  Date: ['Date'],
  FileName: ['File_Name'],
  Type: ['Document_Type'],
  Vendor: ['Vendor'],
  RelatedRecord: ['Related_Record_ID'],
  DriveLink: ['Drive_Link'],
  GmailLink: ['Gmail_Link']
};
const pendingPayments = payments.filter(row => /PENDING|PARTIALLY|UNPAID|OVERDUE|DUE|OPEN|AWAITING/i.test(status(row)));
const reviewRows = [...payments, ...quotes, ...timeline, ...contributions].filter(needsReview);
const paidPayments = payments.filter(paid);
const linkedPayments = payments.filter(hasLink);
const linkedDocuments = documents.filter(hasLink);
const linkedTimeline = timeline.filter(hasLink);
const linkedInvoices = invoices.filter(hasLink);
let focused = {};

if (route.incompleteRequest) {
  focused = { instruction: 'The request is incomplete. Ask the user what scope or period they want, without providing figures.' };
} else if (route.intent === 'links_lookup') {
  focused = {
    instruction: 'Use recent memory to identify the previously discussed records. If there are matching linked rows, return their URLs now.',
    recent_linked_payments: cap(sortByDateDesc(linkedPayments, ['Date we got Invoice', 'Date Paid']).map(row => compactRow(row, paymentKeys)), 40),
    recent_linked_invoices: cap(sortByDateDesc(linkedInvoices).map(row => compactRow(row, {
      Date: ['Date'], Vendor: ['Vendor'], InvoiceNumber: ['Invoice_Number'], Amount: ['Amount_Inc_GST'], Status: ['Status'], DriveLink: ['Drive_Link'], GmailLink: ['Gmail_Link']
    })), 40),
    recent_linked_events: cap(sortByDateDesc(linkedTimeline).map(row => compactRow(row, {
      Date: ['Date'], Description: ['Description'], Status: ['Status'], RelatedRecord: ['Related_Record_ID'], DriveLink: ['Drive_Link', 'Linked Documents'], GmailLink: ['Gmail Link']
    })), 40),
    recent_linked_documents: cap(sortByDateDesc(linkedDocuments).map(row => compactRow(row, documentKeys)), 80)
  };
} else if (route.intent === 'contributions') {
  focused = {
    authoritative_total_aud: contributions.reduce((sum, row) => sum + amount(get(row, ['Amount', 'Amount_AUD'])), 0).toFixed(2),
    authoritative_totals_by_contributor_aud: totalsBy(contributions, ['Contributor'], ['Amount', 'Amount_AUD']),
    contribution_rows: cap(sortByDateDesc(contributions).map(row => compactRow(row, {
      Date: ['Date'], Contributor: ['Contributor'], Amount: ['Amount', 'Amount_AUD'], Source: ['Source'], Description: ['Description'], Statement: ['Statement Link', 'Drive_Link'], Gmail: ['Gmail Link']
    })), 120),
    instruction: 'Use the authoritative precomputed totals exactly. Do not regroup or estimate contributor amounts.'
  };
} else if (route.intent === 'operating_expenses') {
  focused = {
    operating_expenses: cap(sortByDateDesc(operatingExpenses).map(row => compactRow(row, {
      Date: ['Date'], Vendor: ['Vendor'], Type: ['Expense_Type'], Amount: ['Amount_Inc_GST', 'Amount_AUD'], Status: ['Status'], Description: ['Description'], NeedReview: ['Need_Review'], DriveLink: ['Drive_Link'], GmailLink: ['Gmail_Link']
    })), 120),
    instruction: 'Do not calculate a grand total unless duplicates have been reconciled. The tab may contain both consolidated multi-vendor records and their individual bills; itemize known rows and flag overlap risk.'
  };
} else if (route.intent === 'invoices') {
  focused = {
    invoices: cap(sortByDateDesc(invoices).map(row => compactRow(row, {
      Date: ['Date'], Vendor: ['Vendor'], InvoiceNumber: ['Invoice_Number'], Amount: ['Amount_Inc_GST'], Status: ['Status'], Description: ['Description'], NeedReview: ['Need_Review'], DriveLink: ['Drive_Link'], GmailLink: ['Gmail_Link']
    })), 100),
    payment_sources: cap(sortByDateDesc(payments, ['Date we got Invoice']).map(row => compactRow(row, paymentKeys)), 100),
    linked_documents: cap(sortByDateDesc(linkedDocuments).map(row => compactRow(row, documentKeys)), 120)
  };
} else if (route.intent === 'payments') {
  focused = {
    payments: cap(sortByDateDesc(payments, ['Date we got Invoice', 'Date Paid']).map(row => compactRow(row, paymentKeys)), 100),
    linked_documents: cap(sortByDateDesc(linkedDocuments).map(row => compactRow(row, documentKeys)), 120)
  };
} else if (route.intent === 'pending_payments') {
  focused = {
    pending_payments: cap(sortByDateDesc(pendingPayments, ['Date we got Invoice', 'Date Paid']).map(row => compactRow(row, paymentKeys)), 80),
    needs_review: cap(reviewRows.map(row => compactRow(row, paymentKeys)), 40),
    linked_source_rows: cap(sortByDateDesc(linkedPayments, ['Date we got Invoice', 'Date Paid']).map(row => compactRow(row, paymentKeys)), 40)
  };
} else if (route.intent === 'timeline') {
  focused = {
    timeline: cap(sortByDateDesc(timeline).map(row => compactRow(row, {
      Date: ['Date'], Description: ['Description'], Status: ['Status'], RelatedRecord: ['Related_Record_ID'], DriveLink: ['Drive_Link', 'Linked Documents'], GmailLink: ['Gmail Link']
    })), 100),
    related_payment_records: cap(sortByDateDesc(payments, ['Date we got Invoice', 'Date Paid']).map(row => compactRow(row, paymentKeys)), 30),
    linked_documents: cap(sortByDateDesc(linkedDocuments).map(row => compactRow(row, documentKeys)), 50)
  };
} else if (route.intent === 'documents') {
  focused = {
    documents: cap(sortByDateDesc(documents).map(row => compactRow(row, documentKeys)), 120),
    related_payments: cap(sortByDateDesc(linkedPayments, ['Date we got Invoice', 'Date Paid']).map(row => compactRow(row, paymentKeys)), 60)
  };
} else if (route.intent === 'quotes') {
  focused = {
    quotes: cap(sortByDateDesc(quotes).map(row => compactRow(row, {
      Date: ['Date'], Vendor: ['Vendor'], QuoteNumber: ['Quote Number', 'Quote_Number'], Amount: ['Amount'], Status: ['Status'], Decision: ['Decision'], NeedReview: ['Need Review'], Documents: ['Linked Documents', 'Drive_Link'], Gmail: ['Links to Gmail']
    })), 100)
  };
} else if (route.intent === 'weekly_summary') {
  const weekPayments = payments.filter(row => inLastDays(row, ['Date Paid', 'Date we got Invoice'], 7));
  const weekTimeline = timeline.filter(row => inLastDays(row, ['Date'], 7));
  focused = {
    week_payments: cap(sortByDateDesc(weekPayments, ['Date Paid', 'Date we got Invoice']).map(row => compactRow(row, paymentKeys)), 60),
    week_events: cap(sortByDateDesc(weekTimeline).map(row => compactRow(row, {
      Date: ['Date'], Description: ['Description'], Status: ['Status'], DriveLink: ['Drive_Link', 'Linked Documents'], GmailLink: ['Gmail Link']
    })), 60),
    contribution_total_to_date_aud: contributions.reduce((sum, row) => sum + amount(get(row, ['Amount', 'Amount_AUD'])), 0).toFixed(2),
    instruction: 'Do not add payments that appear to be duplicate or related records on the same date/vendor. Present them as rows needing confirmation before stating a weekly aggregate.'
  };
} else {
  focused = {
    authoritative_contribution_total_aud: contributions.reduce((sum, row) => sum + amount(get(row, ['Amount', 'Amount_AUD'])), 0).toFixed(2),
    authoritative_contributions_by_person_aud: totalsBy(contributions, ['Contributor'], ['Amount', 'Amount_AUD']),
    pending_payments: cap(sortByDateDesc(pendingPayments, ['Date we got Invoice']).map(row => compactRow(row, paymentKeys)), 30),
    recent_payments_with_links: cap(sortByDateDesc(linkedPayments, ['Date we got Invoice']).map(row => compactRow(row, paymentKeys)), 15),
    recent_events_with_links: cap(sortByDateDesc(linkedTimeline).map(row => compactRow(row, {
      Date: ['Date'], Description: ['Description'], Status: ['Status'], DriveLink: ['Drive_Link', 'Linked Documents'], GmailLink: ['Gmail Link']
    })), 20)
  };
}

focused.dashboard = sheetData.Dashboard || [];
const contextBudgetChars = 50000;
let focusedText = JSON.stringify(focused, null, 2);
if (focusedText.length > contextBudgetChars) {
  for (const key of Object.keys(focused)) {
    if (Array.isArray(focused[key]) && focusedText.length > contextBudgetChars) {
      focused[key] = focused[key].slice(0, Math.max(4, Math.ceil(focused[key].length / 3)));
      focusedText = JSON.stringify(focused, null, 2);
    }
  }
  focused.context_trimmed_for_token_safety = true;
  focusedText = JSON.stringify(focused, null, 2);
}

const currentChatId = String(route.chatId || '');
const recentMemory = memory
  .filter(row => !currentChatId || String(get(row, ['Chat_ID', 'Chat ID']) || '') === currentChatId)
  .slice(-16)
  .map(row => ({
    timestamp: get(row, ['Timestamp']),
    role: get(row, ['Role']),
    message: String(get(row, ['Message']) || '').slice(0, 700)
  }));

const system = `You are the financial assistant for a residential construction project.

Reply in ${route.responseLanguage || 'English'}, matching the user's latest message.
Use ONLY the focused Google Sheet data below. Never invent totals, amounts, dates, vendors, statuses, Gmail links or Drive links.
Payments is the primary operational view for payment questions.
When a value is precomputed as authoritative, repeat it exactly; do not recalculate it.
For any total, summary or "net position" figure, use the dashboard data below as the single source of truth — never recompute totals from raw Payments/Invoices/Operating_Expenses/Contributions rows if the dashboard already provides that figure.
If two rows have the same vendor/date or appear related, never merge them into a single amount without explicit proof. State that there are separate records and request confirmation if a combined total is uncertain.
If the user asks for Gmail or Google Drive links, provide all matching full URLs exactly as shown. Never claim links are missing while any matching focused row contains a URL.
For a short follow-up such as "Can I have the links?", use Recent memory to identify the subject, then retrieve matching URL rows from focused data.
If the prompt says a request is incomplete, ask one concise clarification question and provide no assumed summary.
Do not claim you searched Gmail or Drive directly; you read links stored in the sheet.
Keep Telegram answers short and factual. Plain text only, no Markdown tables and no emoji.

Intent: ${route.intent}
Focused sheet data:
${focusedText}

Recent memory:
${JSON.stringify(recentMemory, null, 2)}`;

return {
  json: {
    model: 'claude-sonnet-4-5',
    max_tokens: 850,
    system,
    messages: [{ role: 'user', content: route.userMessage }],
    chatId: route.chatId,
    userMessage: route.userMessage,
    timestamp: route.timestamp || new Date().toISOString(),
    intent: route.intent,
    responseLanguage: route.responseLanguage
  }
};

const route = $('Normalize + Route').item.json;

let response = 'Sorry, I could not process the request.';

try {
  response = $input.item.json.content?.[0]?.text || response;
} catch (e) {}

response = String(response || '')
  .replace(/\r/g, '')
  .replace(/^#{1,6}\s*/gm, '')
  .replace(/\*\*/g, '')
  .replace(/__+/g, '')
  .replace(/[✅⚠️❗📧💰📋🔍📅💡]/g, '')
  .trim();

if (!response) {
  response = 'Sorry, I could not find enough data to answer that.';
}

response = response.slice(0, 3900);

return {
  json: {
    response,
    userMessage: route.userMessage,
    chatId: route.chatId,
    timestamp: new Date().toISOString(),
    intent: route.intent,
    responseLanguage: route.responseLanguage || 'English'
  }
};
